prompts=[item[3] for item in items]
assert len(set(prompts))==len(prompts), "вопросы должны различаться"
assert not any("№" in p for p in prompts), "без служебной нумерации"
assert all(0<e-s<=25 for _,s,e,*_ in items), "окно 10–25 с"
out=[]
for yid,s,e,q,a,v,val,src in items:
    out.append(dict(category=C,kind="video",curtain=True,value=val,prompt=q,answer=a,variants=v,youtube_id=yid,start_seconds=s,end_seconds=e,source=src+f"; https://youtu.be/{yid}"))
json.dump(out,open("video.json","w"),ensure_ascii=False,indent=1)
print(len(out))
